import * as THREE from 'three';
import {EffectComposer} from 'three/addons/postprocessing/EffectComposer.js';
import {RenderPass} from 'three/addons/postprocessing/RenderPass.js';
import {OutputPass} from 'three/addons/postprocessing/OutputPass.js';
import {UnrealBloomPass} from 'three/addons/postprocessing/UnrealBloomPass.js';
import {SSAOPass} from 'three/addons/postprocessing/SSAOPass.js';
import {RoomEnvironment} from 'three/addons/environments/RoomEnvironment.js';
import {GLTFLoader} from 'three/addons/loaders/GLTFLoader.js';

export const PRESETS={low:{dpr:1,shadow:512,bloom:false,ao:false,particles:40},medium:{dpr:1.25,shadow:1024,bloom:true,ao:false,particles:100},high:{dpr:1.5,shadow:2048,bloom:true,ao:true,particles:180},ultra:{dpr:2,shadow:2048,bloom:true,ao:true,particles:260}};
export function createGraphics({renderer,scene,camera,stage,config}){
 let preset='medium';try{const saved=localStorage.getItem('po-game-graphics');if(PRESETS[saved])preset=saved}catch{}
 if((navigator.deviceMemory||8)<4)preset='low';let composer=null,ao=null,quality=PRESETS[preset],elapsed=0,frames=0,particles,time=0,disposed=false;
 renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=.96;
 for(const light of [...scene.children].filter(o=>o.isLight))scene.remove(light);
 const fill=new THREE.HemisphereLight(0xbcd8f5,0x303023,1.45),sun=new THREE.DirectionalLight(0xffe2ba,2.7),rim=new THREE.DirectionalLight(0x85b8e8,.65);sun.position.set(-8,18,8);rim.position.set(7,8,-12);sun.castShadow=true;Object.assign(sun.shadow.camera,{left:-30,right:30,top:30,bottom:-30,near:.5,far:70});sun.shadow.normalBias=.025;sun.shadow.bias=-.00015;sun.shadow.radius=3;scene.add(fill,sun,rim);
 const pmrem=new THREE.PMREMGenerator(renderer),room=new RoomEnvironment(),env=pmrem.fromScene(room,.04);scene.environment=env.texture;scene.environmentIntensity=.42;room.dispose();pmrem.dispose();
 const textures=new Set();function grain(style){const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const ctx=canvas.getContext('2d'),image=ctx.createImageData(256,256);let seed=47;const random=()=>{seed=(seed*16807)%2147483647;return(seed-1)/2147483646};for(let y=0;y<256;y++)for(let x=0;x<256;x++){const i=(y*256+x)*4,noise=random(),weave=style==='felt'?(Math.sin(x*Math.PI)*.03+(x%3===0||y%3===0?-.1:0)):style==='wood'?Math.sin(x*.3+Math.sin(y*.08)*2)*.1:style==='turf'?(x%2===0?-.06:0):0,v=Math.max(0,Math.min(255,(.78+noise*.2+weave)*255));image.data[i]=image.data[i+1]=image.data[i+2]=v;image.data[i+3]=255}ctx.putImageData(image,0,0);const t=new THREE.CanvasTexture(canvas);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(style==='felt'?4:2,style==='felt'?4:2);t.colorSpace=THREE.SRGBColorSpace;t.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());textures.add(t);return t}
 const style=config.genre.includes('Craft')?'felt':config.genre.includes('car')?'turf':config.genre.includes('voxel')?'wood':'stone',surface=grain(style),rough=grain('stone');rough.colorSpace=THREE.NoColorSpace;
 const seenMaterials=new WeakSet();function decorate(){scene.traverse(o=>{if(!o.isMesh)return;for(const m of Array.isArray(o.material)?o.material:[o.material]){if(!m?.isMeshStandardMaterial||seenMaterials.has(m))continue;seenMaterials.add(m);if(!m.map&&!o.isSkinnedMesh&&!m.emissive?.getHex()){m.map=surface;m.roughnessMap=rough;m.roughness=.85;m.needsUpdate=true}for(const key of ['map','normalMap','roughnessMap','metalnessMap','aoMap'])if(m[key]){m[key].anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());m[key].needsUpdate=true}if(m.normalMap)m.normalScale.set(.65,.65);m.envMapIntensity=.5}})}
 // Decorative exports contain no colliders, gameplay state or camera controls.
 new GLTFLoader().load('models/environment.glb',g=>{if(disposed)return;g.scene.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true}});scene.add(g.scene);decorate()},undefined,()=>{});
 const geometry=new THREE.BufferGeometry(),positions=new Float32Array(260*3),bases=new Float32Array(260*3);let seed=17;for(let i=0;i<260;i++){seed=seed*16807%2147483647;const x=(seed%1000)/1000;seed=seed*16807%2147483647;const z=(seed%1000)/1000;positions[i*3]=(x-.5)*55;positions[i*3+1]=2+(i%23)*.35;positions[i*3+2]=(z-.5)*45}bases.set(positions);geometry.setAttribute('position',new THREE.BufferAttribute(positions,3));particles=new THREE.Points(geometry,new THREE.PointsMaterial({color:0xc8d9de,size:.028,transparent:true,opacity:.23,depthWrite:false}));scene.add(particles);
 const panel=document.createElement('section');panel.className='graphics-panel';panel.hidden=true;panel.setAttribute('aria-label','Graphics settings');panel.innerHTML='<header><strong>Graphics</strong><button data-graphics-close aria-label="Close graphics settings">×</button></header><label>Quality <select id="graphics-preset"><option value="low">Low · lighter rendering</option><option value="medium">Medium · balanced</option><option value="high">High · ambient occlusion</option><option value="ultra">Ultra · sharper rendering</option></select></label><p>Visual settings only. Game rules, controls and camera stay the same.</p><div id="graphics-details"></div><small>FPS is measured here; performance depends on your device.</small>';document.body.append(panel);
 const toggle=document.createElement('button');toggle.id='graphics-button';toggle.textContent='Graphics';document.querySelector('.game-header nav').insertBefore(toggle,document.getElementById('pause-button'));toggle.onclick=()=>panel.hidden=!panel.hidden;panel.querySelector('[data-graphics-close]').onclick=()=>panel.hidden=true;
 const metrics=document.createElement('span');metrics.className='graphics-metrics';metrics.setAttribute('aria-live','off');document.querySelector('.game-bottom').append(metrics);
 function disposeComposer(){if(composer){for(const pass of composer.passes)pass.dispose?.();composer.dispose();composer=null}}
 function apply(){quality=PRESETS[preset];renderer.setPixelRatio(Math.min(devicePixelRatio,quality.dpr));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;sun.shadow.mapSize.set(quality.shadow,quality.shadow);sun.shadow.map?.dispose();sun.shadow.map=null;geometry.setDrawRange(0,quality.particles);disposeComposer();const size=renderer.getSize(new THREE.Vector2());
  if(quality.bloom||quality.ao)try{const target=new THREE.WebGLRenderTarget(Math.max(1,size.x),Math.max(1,size.y),{type:THREE.HalfFloatType,samples:renderer.capabilities.isWebGL2?4:0});composer=new EffectComposer(renderer,target);composer.addPass(new RenderPass(scene,camera));if(quality.ao){ao=new SSAOPass(scene,camera,size.x,size.y,preset==='ultra'?12:8);ao.kernelRadius=.6;ao.minDistance=.003;ao.maxDistance=.12;composer.addPass(ao)}if(quality.bloom){const bloom=new UnrealBloomPass(new THREE.Vector2(size.x,size.y),.16,.4,1.15);composer.addPass(bloom)}composer.addPass(new OutputPass())}catch(error){disposeComposer();console.warn('Post-processing unavailable; using direct rendering.',error)}
  panel.querySelector('#graphics-preset').value=preset;panel.querySelector('#graphics-details').textContent=`${quality.shadow}px soft shadows · DPR up to ${quality.dpr} · ${quality.ao?'SSAO':'no SSAO'} · ${quality.bloom?'subtle bloom':'direct render'}`;resize();}
 function resize(){const r=stage.getBoundingClientRect();renderer.setSize(r.width,r.height);composer?.setSize(r.width,r.height)}
 panel.querySelector('#graphics-preset').onchange=e=>{preset=e.target.value;try{localStorage.setItem('po-game-graphics',preset)}catch{}apply()};apply();
 if(config.title.includes('Rift')){const glow=new THREE.MeshStandardMaterial({color:0x785bd5,emissive:0x7851ed,emissiveIntensity:2,roughness:.4});for(const z of [-16.5,16.5]){const halo=new THREE.Mesh(new THREE.TorusGeometry(2.28,.035,6,48),glow);halo.position.set(0,3.6,z);scene.add(halo)}}
const originalReset=renderer.info.autoReset;renderer.info.autoReset=false;
 return {decorate,resize,render(dt){time+=dt;const array=geometry.attributes.position.array;for(let i=0;i<quality.particles;i++){array[i*3]=bases[i*3]+Math.sin(time*.13+i)*.15;array[i*3+1]=bases[i*3+1]+Math.sin(time*.2+i)*.09}geometry.attributes.position.needsUpdate=true;renderer.info.reset();try{if(composer)composer.render(dt);else renderer.render(scene,camera)}catch(error){if(composer){disposeComposer();renderer.render(scene,camera);console.warn('Graphics effects disabled after renderer failure.',error)}else throw error}elapsed+=dt;frames++;if(elapsed>=1){metrics.textContent=`${Math.round(frames/elapsed)} FPS · ${renderer.info.render.calls} draws · ${preset.toUpperCase()}`;elapsed=0;frames=0;decorate()}},modelURL(url){return preset==='low'?url.replace(/\.glb$/,'-low.glb'):url},dispose(){disposed=true;renderer.info.autoReset=originalReset;disposeComposer();env.dispose();textures.forEach(t=>t.dispose());geometry.dispose();particles.material.dispose();panel.remove();toggle.remove();metrics.remove()}};
}
